<?php $maxOrders = max(1, ...array_column($orders_by_day, 'value')); $tableTotal = max(1, array_sum($table_status)); ?>
<section class="dashboard-head"><div class="container"><h1>Operasional restoran</h1><p>Prioritaskan antrean terlama dan pantau meja dari status database terkini.</p></div></section>
<section class="section-space pt-0"><div class="container">
    <div class="metric-ledger"><div><span>Order menunggu disajikan</span><strong><?= (int) $summary['received_orders'] ?></strong></div><div><span>Kunjungan aktif</span><strong><?= (int) $summary['active_visits'] ?></strong></div><div><span>Meja terpakai</span><strong><?= (int) $summary['occupied_tables'] ?></strong></div></div>
    <div class="analytics-grid staff-analytics"><section class="analytics-panel"><div class="panel-heading"><div><h2>Arus order 7 hari</h2><p>Semua order baru, termasuk yang sudah disajikan.</p></div><a href="/staff/orders">Buka antrean</a></div><div class="bar-chart" aria-label="Grafik order tujuh hari terakhir"><?php foreach ($orders_by_day as $point): ?><div class="bar-column"><span class="bar-value"><?= (int) $point['value'] ?></span><div class="bar-track"><i style="--bar-height:<?= (int) round(((int) $point['value'] / $maxOrders) * 100) ?>%"></i></div><span><?= e($point['label']) ?></span></div><?php endforeach; ?></div></section><section class="analytics-panel table-composition"><div class="panel-heading"><div><h2>Status meja aktif</h2><p>Berubah hanya lewat checkout dan Kosongkan Meja.</p></div></div><div class="composition-bar"><i style="--share:<?= (int) round(((int) $table_status['occupied'] / $tableTotal) * 100) ?>%"></i></div><div class="composition-legend"><span><b class="dot occupied"></b>Terpakai <strong><?= (int) $table_status['occupied'] ?></strong></span><span><b class="dot available"></b>Tersedia <strong><?= (int) $table_status['available'] ?></strong></span></div><a class="btn btn-outline-leaf" href="/staff/visits">Lihat kunjungan aktif</a></section></div>
    <section class="waiting-panel"><div class="panel-heading"><div><h2>Antrean tertua</h2><p>Maksimal lima order berstatus received.</p></div></div><?php if ($oldest_waiting === []): ?><p class="empty-inline">Tidak ada order yang menunggu disajikan.</p><?php else: ?><div class="waiting-list"><?php foreach ($oldest_waiting as $order): ?><article><div><strong><?= e($order['order_code']) ?></strong><span><?= e($order['customer_name_snapshot']) ?> · Meja <?= e($order['table_code']) ?></span></div><time datetime="<?= e($order['created_at']) ?>"><?= e(date('H:i', strtotime($order['created_at']))) ?></time></article><?php endforeach; ?></div><?php endif; ?></section>
</div></section>
